using System;using System.Collections.Generic;using Unity.Mathematics;namespace Unity.Collections{public struct NativeStream:IDisposable{
 internal sealed class Store{internal List<int2>[] Rows;internal bool[] Closed;internal int Writes;}
 static int next;static readonly Dictionary<int,Store> stores=new Dictionary<int,Store>();readonly int id;
 public NativeStream(int count,Allocator allocator):this(count){}public bool IsCreated=>id!=0&&stores.ContainsKey(id);public NativeStream(int count){if(count<1||count>32)throw new NotSupportedException("Path batch1..32");id=++next;var s=new Store{Rows=new List<int2>[count],Closed=new bool[count]};for(int i=0;i<count;i++)s.Rows[i]=new List<int2>();stores.Add(id,s);}
 public Writer AsWriter()=>new Writer{id=id,row=-1};public Reader AsReader()=>new Reader{id=id,row=-1};public void Dispose(){stores.Remove(id);}
 public struct Writer{internal int id,row;public void BeginForEachIndex(int i){var s=stores[id];if(row!=-1||i<0||i>=s.Rows.Length||s.Closed[i])throw new NotSupportedException();row=i;}public void Write<T>(T value){if(typeof(T)!=typeof(int2)||row<0)throw new NotSupportedException();var s=stores[id];if(s.Writes++>=1048576)throw new NotSupportedException("Path stream bound");s.Rows[row].Add((int2)(object)value);}public void EndForEachIndex(){stores[id].Closed[row]=true;row=-1;}}
 public struct Reader{internal int id,row,pos;public int BeginForEachIndex(int i){var s=stores[id];if(row!=-1||!s.Closed[i])throw new NotSupportedException("Incomplete original path output");row=i;pos=0;return s.Rows[i].Count;}public T Read<T>(){if(typeof(T)!=typeof(int2))throw new NotSupportedException();return(T)(object)stores[id].Rows[row][pos++];}public void EndForEachIndex(){if(pos!=stores[id].Rows[row].Count)throw new NotSupportedException();row=-1;}}
}}
